def transform(grid):
    # A compact five-row pattern is replicated at every isolated marker,
    # aligned by the marker's location within the pattern. Components need
    # diagonal connectivity because pattern cells may only touch diagonally.
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            q = [(r, c)]; seen.add((r, c)); comp = []
            while q:
                y, x = q.pop(); comp.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != bg and (ny, nx) not in seen:
                            seen.add((ny, nx)); q.append((ny, nx))
            comps.append(comp)
    # The source template is the five-cell connected object; isolated 8s are markers.
    seed = next(comp for comp in comps if len(comp) > 1)
    r0, r1 = min(r for r, c in seed), max(r for r, c in seed)
    c0, c1 = min(c for r, c in seed), max(c for r, c in seed)
    pattern = [[grid[r][c] for c in range(c0, c1 + 1)] for r in range(r0, r1 + 1)]
    # Isolated 0s indicate where to copy the template.
    seed_set = set(seed)
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0]
    out = [row[:] for row in grid]
    # Center the pattern's bounding box on each isolated marker.
    anchor_r, anchor_c = len(pattern) // 2, len(pattern[0]) // 2
    for mr, mc in markers:
        for pr, row in enumerate(pattern):
            for pc, value in enumerate(row):
                rr, cc = mr + pr - anchor_r, mc + pc - anchor_c
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                    out[rr][cc] = value
    return out

